def step(w,l,s):
    # orthog via QR
    V=np.array([l**j for j in range(s+1)]).T
    Q,R=np.linalg.qr(np.sqrt(w)[:,None]*V)
    p=np.linalg.solve(R[:s,:s],-R[:s,s]); p=np.r_[p,1.]
    v=V@p
    return w*v*v/np.dot(w,v*v),np.dot(w,v*v),p
for s in [2,3]:
 l=np.linspace(-1,1,2*s)
 w=np.arange(1,2*s+1,dtype=float); w/=sum(w)
 for k in range(10000):
  w,f,p=step(w,l,s)
