from math import sqrt
l=np.array([-sqrt(2+sqrt(2)),-sqrt(2-sqrt(2)),sqrt(2-sqrt(2)),sqrt(2+sqrt(2))])
def step(w):
 w=w/sum(w)
 m1=w@l;m2=w@(l*l);m3=w@(l**3)
 b=(m1*m2-m3)/(m2-m1*m1);a=-m2-b*m1
 p=l*l+b*l+a
 return w*p*p/(w@(p*p))
def G(w):return step(step(w))
for u in [0,.1,.5,1,1.3]:
 for x in [0,.1]:
  O=(1+u/sqrt(2))/2;I=1-O
  kap=(sqrt(2)-u)/(sqrt(2)+u)*(-l[0]/l[2]);D=kap*x
  w=np.array([(O-x)/2,(I-D)/2,(I+D)/2,(O+x)/2])
  J=np.column_stack([(G(w+np.eye(4)[i]*1e-6)-G(w-np.eye(4)[i]*1e-6))/2e-6 for i in range(4)])
  print(u,x,w,np.linalg.eigvals(J))
